// Bundles src/ui into src/worker/ui.gen.ts (the Worker serves the app itself; Assets only holds the SDK files).
import { build } from 'esbuild';
import fs from 'node:fs';
if (!fs.existsSync('wrangler.jsonc')) { fs.copyFileSync('wrangler.example.jsonc', 'wrangler.jsonc'); console.log('created wrangler.jsonc from wrangler.example.jsonc'); }
const settings = JSON.parse(fs.readFileSync('spekkr.inputs.json', 'utf8'));
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const r = await build({ entryPoints: ['src/ui/app.ts'], bundle: true, minify: true, format: 'esm', target: 'es2022', write: false, platform: 'browser' });
const js = r.outputFiles[0].text;
// rrweb-player (MIT) for session replay, loaded on demand from /player.js and /player.css.
const pr = await build({ entryPoints: ['src/ui/player.ts'], bundle: true, minify: true, format: 'esm', target: 'es2022', write: false, platform: 'browser' });
const playerJs = pr.outputFiles[0].text;
const playerCss = fs.readFileSync('node_modules/rrweb-player/dist/style.min.css', 'utf8').replace(/\/\*# sourceMappingURL=.*?\*\//g, '');
const brand = /^#[0-9a-f]{6}$/i.test(settings.brand_color ?? '') ? settings.brand_color : '#1d4ed8';
const css = fs.readFileSync('src/ui/style.css', 'utf8').replaceAll('__BRAND__', brand);
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(settings.app_name ?? 'Analytics')}</title><link rel="stylesheet" href="/app.css"></head><body><div id="app"></div><script type="module" src="/app.js"></script></body></html>`;
fs.writeFileSync('src/worker/ui.gen.ts', `// Generated by scripts/build-ui.mjs. Do not edit.\nexport default ${JSON.stringify({ html, js, css, playerJs, playerCss, appName: settings.app_name ?? 'Analytics' })};\n`);
console.log(`ui: js ${js.length} bytes, css ${css.length} bytes, player ${playerJs.length + playerCss.length} bytes`);
